arguments.command:
cd /workspace && OPENBLAS_NUM_THREADS=1 LD_LIBRARY_PATH=/workspace/native PYTHONPATH=/workspace/.deps:/workspace/submission:/workspace/tests python3 - <<'EOF'
import random, sys
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tests')
from protocol import validate, InvalidRequest
import gen as G
for seed in (1175,1212,5001,5009,5027,5037):
    rng=random.Random(seed); req=G.gen_request(rng)
    for ci,case in enumerate(req['cases']):
        found=False
        for k in range(1,len(case['events'])+1):
            try: validate({'cases':[dict(case,events=case['events'][:k])]})
            except InvalidRequest:
                print('seed',seed,'case',ci,'fails at event',k)
                print('   ',case['events'][k-1])
                print('    slots:',[c['paths'] for c in case['commodities']])
                found=True; break
        if not found: print('seed',seed,'case',ci,'STRUCTURAL')
EOF
